    /// <summary>
    /// Runs the pack change operations
    /// </summary>
    public void startOperation()
    {        
        if (this.validate())
        {
            ttsbegin;

            this.replaceOriginalItemSiteInfo(
                    inventItemPurchSetupOrigItem, inventItemPurchSetupTempItem, 
                    inventItemSalesSetupOrigItem, inventItemSalesSetupTempItem, 
                    metItemSiteSettingsSetupOriginal, metItemSiteSettingsSetupTemp);

            this.createBarcode(metItemSiteSettingsSetupOriginal, metItemSiteSettingsSetupTemp);
            this.createPhysicalDim(metItemSiteSettingsSetupOriginal, whsPhysDimUOMTempItem);
            this.updateItemStatus(metItemSiteSettingsSetupOriginal, METConstants::Active);
            this.updateItemStatus(metItemSiteSettingsSetupTemp, METConstants::Discontinued, true);
            this.rePriceOpenSalesOrders();
            this.processSlowMovingItems();

            ttscommit;
        }
    }

    /// <summary>
    /// Validates the data supplied to this class
    /// </summary>
    /// <returns>Validation result</returns>
    private boolean validate()
    {
        boolean ret = true;
        
        if (metItemSiteSettingsSetupOriginal.ItemStatus != METConstants::packChange)
        {
            ret = checkFailed("@MET:METPackChangeError");
        }

        //ret = this.checkStock() && ret;

        //ret = this.checkOpenPurchQty() && ret;

        return ret;
    }

    /// <summary>
    /// Checks the item stock
    /// </summary>
    /// <returns>true or false</returns>
    private boolean checkStock()
    {
        InventQtyAvailPhysical availPhys;
        boolean ret = true;
        InventDim inventDim;
        inventDim.InventSiteId = metItemSiteSettingsSetupOriginal.InventSiteId;
        inventDim = InventDim::findOrCreate(inventDim);

        InventOnhand    inventOnhand;
        InventDimParm   inventDimParm;

        inventDimParm.initFromInventDim(inventDim);
        inventOnhand = InventOnhand::newParameters(metItemSiteSettingsSetupOriginal.ItemId, inventDim, inventDimParm);
        
        availPhys = inventOnhand.availPhysical();

        if (inventOnhand.availPhysical() > 0)
        {
            ret = checkFailed("@MET:METPackChangeStockError");
        }

        return ret;
    }

    /// <summary>
    /// Checks the item open purchase qty
    /// </summary>
    /// <returns>true or false</returns>
    private boolean checkOpenPurchQty()
    {
        boolean ret = true;

        InventTrans inventTrans;
        InventTransOrigin inventTransOrigin;

        select sum(Qty) from inventTrans
            where inventTrans.ItemId == metItemSiteSettingsSetupOriginal.ItemId
            && inventTrans.StatusReceipt == StatusReceipt::Ordered
        join RecId, ReferenceCategory from inventTransOrigin
            where inventTransOrigin.RecId == inventTrans.inventTransOrigin
            && inventTransOrigin.ReferenceCategory == InventTransType::Purch;

        if (inventTrans.Qty > 0)
        {
            ret = checkFailed("@MET:METPackChangePurchQtyError");
        }

        return ret;
    }

    /// <summary>
    /// Replace the original item info from temp item info
    /// </summary>
    /// <param name = "_inventItemPurchSetupOrigItem">The original purchase item setup buffer</param>
    /// <param name = "_inventItemPurchSetupTempItem">The temp purchase item setup buffer</param>
    /// <param name = "_inventItemSalesSetupOrigItem">The original sales item setup buffer</param>
    /// <param name = "_inventItemSalesSetupTempItem">The temp sales item setup buffer</param>
    /// <param name = "_metItemSiteSettingsSetupOriginal">The original item site settings setup buffer</param>
    /// <param name = "_metItemSiteSettingsSetupTemp">The temp item site settings setup buffer</param>
    private void replaceOriginalItemSiteInfo(
        InventItemPurchSetup _inventItemPurchSetupOrigItem,
        InventItemPurchSetup _inventItemPurchSetupTempItem,
        InventItemSalesSetup _inventItemSalesSetupOrigItem,
        InventItemSalesSetup _inventItemSalesSetupTempItem,
        MetItemSiteSettingsSetup _metItemSiteSettingsSetupOriginal,
        MetItemSiteSettingsSetup _metItemSiteSettingsSetupTemp)
    {
        
        MetInventTable METInventTableOrig = METInventTable::find(_metItemSiteSettingsSetupOriginal.ItemId, true);
        MetInventTable METInventTableTemp = METInventTable::find(_metItemSiteSettingsSetupTemp.ItemId);

        if (METInventTableOrig)
        {
            METInventTableOrig.ItemSize = METInventTableTemp.ItemSize;
            METInventTableOrig.update();
        }

        _inventItemPurchSetupOrigItem.selectForUpdate(true);
        _inventItemPurchSetupOrigItem.METPurchUnit = _inventItemPurchSetupTempItem.METPurchUnit;
        _inventItemPurchSetupOrigItem.update();

        _inventItemSalesSetupOrigItem.selectForUpdate(true);
        _inventItemSalesSetupOrigItem.METSalesUnit = _inventItemSalesSetupTempItem.METSalesUnit;
        _inventItemSalesSetupOrigItem.update();

        _metItemSiteSettingsSetupOriginal.selectForUpdate(true);
        _metItemSiteSettingsSetupOriginal.CartonPerPallet = _metItemSiteSettingsSetupTemp.CartonPerPallet;
        _metItemSiteSettingsSetupOriginal.CartonPerLayer = _metItemSiteSettingsSetupTemp.CartonPerLayer;
        _metItemSiteSettingsSetupOriginal.PalletLayerQty = _metItemSiteSettingsSetupTemp.PalletLayerQty;
        _metItemSiteSettingsSetupOriginal.Layers = _metItemSiteSettingsSetupTemp.Layers;
        _metItemSiteSettingsSetupOriginal.PalletQty = _metItemSiteSettingsSetupTemp.PalletQty;
        _metItemSiteSettingsSetupOriginal.update();
    }

    /// <summary>
    /// Creates Physical dimensions
    /// </summary>
    /// <param name = "_metItemSiteSettingsSetupOriginal">The original site settings buffer</param>
    /// <param name = "_whsPhysDimUOMTempItem">The temp physical dimension buffer</param>
    private void createPhysicalDim(
        MetItemSiteSettingsSetup _metItemSiteSettingsSetupOriginal,
        WHSPhysDimUOM _whsPhysDimUOMTempItem)
    {
        WHSPhysDimUOM whsPhysDimUOM;
        select forupdate whsPhysDimUOM
            where whsPhysDimUOM.ItemId == _metItemSiteSettingsSetupOriginal.ItemId
            && whsPhysDimUOM.UOM == whsPhysDimUOMTempItem.UOM
            && whsPhysDimUOM.PhysDimId == whsPhysDimUOMTempItem.PhysDimId;

        if (whsPhysDimUOM.RecId)
        {
            buf2Buf(_whsPhysDimUOMTempItem, whsPhysDimUOM);
            whsPhysDimUOM.update();
        }
        else 
        {
            buf2Buf(_whsPhysDimUOMTempItem, whsPhysDimUOM);
            whsPhysDimUOM.ItemId = _metItemSiteSettingsSetupOriginal.ItemId;
            whsPhysDimUOM.insert();
        }
    }

    /// <summary>
    /// Creates the barcodes
    /// </summary>
    /// <param name = "_metItemSiteSettingsSetupOriginal">The original item site settings buffer</param>
    private void createBarcode(MetItemSiteSettingsSetup _metItemSiteSettingsSetupOriginal, MetItemSiteSettingsSetup _metItemSiteSettingsSetupTemp)
    {
        InventItemBarcode inventItemBarcode, inventItemBarcodeTemp;

        select inventItemBarcodeTemp where
            inventItemBarcodeTemp.itemId == _metItemSiteSettingsSetupTemp.ItemId;

        inventItemBarcode.clear();
        buf2Buf(inventItemBarcodeTemp, inventItemBarcode);
        inventItemBarcode.ItemId = _metItemSiteSettingsSetupOriginal.ItemId;
        inventItemBarcode.insert();

    }

    /// <summary>
    /// Updates the Item Status for given record
    /// </summary>
    /// <param name = "_metItemSiteSettingsSetup">The record to be updated</param>
    /// <param name = "_itemStatus">The item status to be updated</param>
    /// <param name = "_updateDiscontinued">Discontinue or not</param>
    private void updateItemStatus(MetItemSiteSettingsSetup _metItemSiteSettingsSetup, METItemStatus _itemStatus, boolean _updateDiscontinued = false)
    {
        utcdatetime currentDateTime = DateTimeUtil::getSystemDateTime();
        _metItemSiteSettingsSetup.selectForUpdate(true);
        _metItemSiteSettingsSetup.ItemStatus = _itemStatus;

        if (_updateDiscontinued)
        {
            _metItemSiteSettingsSetup.DiscontinueDate = DateTimeUtil::date(DateTimeUtil::applyTimeZoneOffset(currentDateTime, DateTimeUtil::getUserPreferredTimeZone())) + 3;
        }

        _metItemSiteSettingsSetup.update();
    }

    /// <summary>
    /// Reprice open sales orders
    /// </summary>
    private void rePriceOpenSalesOrders()
    {
        SalesTable salesTable;
        SalesLine salesLine;
        InventUnitId inventUnit;
        SalesUnit salesUnit;
        InventItemInventSetup inventItemInventSetup;
        InventDim inventDim;
        UnitOfMeasureConverter unitOfMeasureConverter;
        UnitOfMeasure unitOfMeasureFrom;
        UnitOfMeasure unitOfMeasureTo;
        UnitOfMeasureConversionRounding rounding;
        UnitOfMeasureConversion unitOfMeasureConversionDirect;   
        
        InventTable inventTable;
        EcoResProduct ecoResProduct;
        InventTableModule inventTableModuleOldPack, inventTableModuleNewPack;
        real factorA, factorB, convertedValue;

        inventDim.clear();
        inventDim.InventSiteId = metItemSiteSettingsSetupOriginal.InventSiteId;
        inventDim = InventDim::findOrCreate(inventDim);
    
        try
        {
            while select RecId from salesTable
                where salesTable.SalesStatus == SalesStatus::Backorder
                && salesTable.DocumentStatus == DocumentStatus::Confirmation    
            join forupdate * from salesLine
                where salesLine.SalesId == salesTable.SalesId
                && salesLine.ItemId == metItemSiteSettingsSetupOriginal.ItemId
                && salesLine.SalesStatus == SalesStatus::Backorder
            join RecId, ItemId from inventTable 
                where InventTable.ItemId == SalesLine.ItemId
            join RecId from ecoResProduct
                where ecoResProduct.RecId == inventTable.Product
            {
                
                //Calculate Factor-A - Old unit to Sales Unit
                inventTableModuleOldPack = InventTableModule::find(inventTable.ItemId, ModuleInventPurchSales::Invent);
                unitOfMeasureFrom = UnitOfMeasure::findBySymbol(inventTableModuleOldPack.UnitId);
                unitOfMeasureTo = UnitOfMeasure::findBySymbol(salesLine.SalesUnit);

                unitOfMeasureConverter = UnitOfMeasureConverter::newFromConversionParameters(unitOfMeasureFrom.RecId, unitOfMeasureTo.RecId, NoYes::No, ecoResProduct.RecId);

                if (unitOfMeasureConverter != null && unitOfMeasureConverter.canValueBeConverted())
                {
                    factorA = unitOfMeasureConverter.convertValue(salesLine.SalesQty);
                }

                //Calculate Factor-B 
                inventTable = inventTable::find(metItemSiteSettingsSetupTemp.ItemId);
                inventTableModuleNewPack = InventTableModule::find(inventTable.ItemId, ModuleInventPurchSales::Invent);
                ecoResProduct = EcoResProduct::find(inventTable.Product);

                //      unitOfMeasureFrom = UnitOfMeasure::findBySymbol(inventTableModuleNewPack.UnitId);
                
                unitOfMeasureTo = UnitOfMeasure::findBySymbol(inventTable.inventItemSalesSetup(inventDim.inventdimId).METSalesUnit);

                unitOfMeasureConverter = UnitOfMeasureConverter::newFromConversionParameters(unitOfMeasureFrom.RecId, unitOfMeasureTo.RecId, NoYes::No, ecoResProduct.RecId);
            
                if (unitOfMeasureConverter != null && unitOfMeasureConverter.canValueBeConverted())
                {
                    factorB = unitOfMeasureConverter.convertValue(salesLine.SalesQty);
                }

                unitOfMeasureConversionDirect = UnitOfMeasureConversion::findByConversion(unitOfMeasureFrom.RecId, unitOfMeasureTo.RecId);
                
                if (factorB != 0)
                {   
                    convertedValue = this.roundValue(factorA / factorB, unitOfMeasureTo, unitOfMeasureConversionDirect.Rounding);
                }
                else
                {
                    convertedValue = salesLine.SalesQty;
                }

                salesLine.SalesUnit = unitOfMeasureTo.Symbol;
                salesline.SalesQty = convertedValue;
                salesLine.update();
            }
        }
        catch(Exception::Error)
        {
            throw Error("@SYS65081");
        }
    }

    private void processSlowMovingItems()
    {
        ReqItemTable reqItemTable, reqItemTableUpdate;
        InventParameters inventParameters = InventParameters::find();
        InventDim inventDim;
        MetItemSiteSettingsSetup metItemSiteSettingsSetupLocal;
        InventItemPurchSetup inventItemPurchSetupLocal;
        InventItemSalesSetup inventItemSalesSetupLocal;

        inventDim.inventSiteId = metItemSiteSettingsSetupOriginal.InventSiteId;
        inventDim = InventDim::findOrCreate(inventDim);
        reqItemTable = reqItemTable::find(metItemSiteSettingsSetupOriginal.ItemId, inventDim.inventDimId, true);
        if (inventParameters.METNDCSite == metItemSiteSettingsSetupOriginal.InventSiteId && (reqItemTable.METOSCCode == 'S' || reqItemTable.METOSCCode == 'V'))
        {
            while select forupdate reqItemTableUpdate
                where reqItemTableUpdate.ItemId == metItemSiteSettingsSetupOriginal.ItemId
                && reqItemTableUpdate.RecId != reqItemTable.RecId
                && reqItemTableUpdate.ReqPOType == ReqPOType::Transfer
                && reqItemTableUpdate.InventLocationIdReqMain == reqItemTable.InventLocationIdReqMain
            join InventSiteId from inventDim
                where inventDim.inventDimId == reqItemTable.CovInventDimId
            {
                select forupdate metItemSiteSettingsSetupLocal
                    where metItemSiteSettingsSetupLocal.ItemId == metItemSiteSettingsSetupOriginal.ItemId
                    && metItemSiteSettingsSetupLocal.InventSiteId == inventDim.InventSiteId;

                    inventItemPurchSetupLocal = InventItemPurchSetup::find(metItemSiteSettingsSetupLocal.ItemId, inventDim.inventDimId);
                    inventItemSalesSetupLocal = InventItemSalesSetup::find(metItemSiteSettingsSetupLocal.ItemId, InventDim.inventDimId);

                    this.replaceOriginalItemSiteInfo(
                        inventItemPurchSetupLocal, inventItemPurchSetupTempItem,
                        inventItemSalesSetupLocal, inventItemSalesSetupTempItem,
                        metItemSiteSettingsSetupLocal, metItemSiteSettingsSetupTemp);

                this.createBarcode(metItemSiteSettingsSetupLocal, metItemSiteSettingsSetupTemp);
                this.createPhysicalDim(metItemSiteSettingsSetupLocal, whsPhysDimUOMTempItem);
                this.updateItemStatus(metItemSiteSettingsSetupLocal, METConstants::Active);
                
            }
        }
    }

    /// <summary>
    /// Gets the Physical dimensions table buffer
    /// </summary>
    /// <param name = "_itemId">Item Id</param>
    /// <returns>The Physical dimensions table buffer</returns>
    public static WHSPhysDimUOM getWhsPhysDimOUM(ItemId _itemId)
    {
        WHSPhysDimUOM whsPhysDimUOM;
        
        select * from whsPhysDimUOM
            where whsPhysDimUOM.itemId == _itemId;

        return whsPhysDimUOM;
    }

    /// <summary>
    /// Gets the Item code table buffer
    /// </summary>
    /// <param name = "_itemId">Item Id</param>
    /// <returns>The Item code table buffer</returns>
    public static InventItemBarcode getInventItembarcode(ItemId _itemId)
    {
        InventItemBarcode inventItembarcode;

        select inventItembarcode
            where inventItembarcode.itemId == _itemId
            && inventItembarcode.useForPrinting == NoYes::Yes;

        return inventItembarcode;
    }

    /// <summary>
    /// Gets the Item site settings buffer
    /// </summary>
    /// <param name = "_itemId">Item Id</param>
    /// <param name = "_inventSiteId">Site id</param>
    /// <returns>The Item site settings buffer</returns>
    public static MetItemSiteSettingsSetup getItemSiteSettingsSetup(ItemId _itemId, InventSiteId _inventSiteId)
    {
        MetItemSiteSettingsSetup metItemSiteSettingsSetup;

        select firstonly metItemSiteSettingsSetup 
            where metItemSiteSettingsSetup.ItemId == _itemId
            && metItemSiteSettingsSetup.InventSiteId == _inventSiteId;

        return metItemSiteSettingsSetup;

    }

    /// <summary>
    /// Round the value using unit conversion rounding rules
    /// </summary>
    /// <param name = "_value">Value to round</param>
    /// <param name = "_toUnit">To unit</param>
    /// <param name = "_rounding">Round method</param>
    /// <returns></returns>
    private real roundValue(real _value, UnitOfMeasure _toUnit, UnitOfMeasureConversionRounding _rounding)
    {
        real    ret;
        int     sign    = 1;
        
        switch (_rounding)
        {
            case UnitOfMeasureConversionRounding::Nearest   :
                ret = decRound(sign * _value, this.roundingDecimalPrecision(_toUnit.RecId));
                break;

            case UnitOfMeasureConversionRounding::Up        :
                ret = roundUpDec(sign * _value, this.roundingDecimalPrecision(_toUnit.RecId));
                break;

            case UnitOfMeasureConversionRounding::Down      :
                ret = roundDownDec(sign * _value, this.roundingDecimalPrecision(_toUnit.RecId));
                break;
        }

        return sign * ret;
    }

    /// <summary>
    /// Rounds the value down
    /// </summary>
    /// <param name = "value">Value to round</param>
    /// <param name = "numDec">Number of decimals</param>
    /// <returns></returns>
    static real roundDownDec(real value, int numDec)
    {
        real            unit = 1;
        while (numDec > 0)
        {
            unit        = unit/10;
            numDec      = numDec-1;
        }

        return roundDown(value, unit);
    }

    /// <summary>
    /// Rounds the value up
    /// </summary>
    /// <param name = "value">Value to round</param>
    /// <param name = "unit">Rounding unit</param>
    /// <returns></returns>
    static real roundUp(real value, real unit)
    {
        real    roundedValue;

        roundedValue = round(value,unit);
        // Check for special case
        if (value== roundedValue)
        {
            return value;
        }
        // for numerical reasons we subtract the major part of the number before rounding
        return round(value - roundedValue + unit/2, unit) + roundedValue;
        
    }

    /// <summary>
    /// Round up to decimal
    /// </summary>
    /// <param name = "value">Value to round</param>
    /// <param name = "numDec">Number of decimals</param>
    /// <returns></returns>
    static real roundUpDec(real value, int numDec)
    {
        real unit = 1;
        while (numDec > 0)
        {
            unit        = unit/10;
            numDec      = numDec-1;
        }

        return roundUp(value,unit);
    }

/// <summary>
/// The rounding decimal precision
/// </summary>
/// <param name = "_toUnit">To unit</param>
/// <returns>Precision value</returns>
private UnitOfMeasureDecimalPrecision roundingDecimalPrecision(RecId _toUnit)
{
    return  UnitOfMeasure::find(_toUnit).DecimalPrecision;
}
